8	See LICENSE in the root of the software repository for the full text of the License.
9	*/
10	
11	#ifndef PTO_COMMON_TASSIGN_CHECK_HPP
12	#define PTO_COMMON_TASSIGN_CHECK_HPP
13	
14	#include <cstddef>
15	#include <pto/common/pto_tile.hpp>
16	
17	// CPUSIM does not model on-chip buffer capacities, so skip all static checks.
18	#if defined(__CPU_SIM) || defined(__COSTMODEL)
19	
20	namespace pto {
21	namespace detail {
22	
23	template <typename TileT, std::size_t Addr>
24	struct tassign_static_check {};
25	
26	} // namespace detail
27	} // namespace pto
28	
29	#else // NPU targets — full static checks
30	
31	#include <pto/common/buffer_limits.hpp>
32	#include <pto/common/memory.hpp>
33	
34	namespace pto {
35	namespace detail {
36	
37	// =============================================================================
38	// TileStorageBytes: compute the byte footprint of a Tile or ConvTile.
39	// =============================================================================
40	
41	template <typename T, typename = void>
42	struct TileStorageBytes;
43	
44	// Regular Tile — Rows * Cols * sizeof(DType)
45	template <typename T>
46	struct TileStorageBytes<T, std::enable_if_t<is_tile_data_v<T> && !is_conv_tile_v<T> > > {
47	    static constexpr std::size_t value =
48	        static_cast<std::size_t>(T::Rows) * static_cast<std::size_t>(T::Cols) * sizeof(typename T::DType);
49	};
50	
51	// ConvTile — uses bufferSize member
52	template <typename T>
53	struct TileStorageBytes<T, std::enable_if_t<is_conv_tile_v<T> > > {
54	    static constexpr std::size_t value = static_cast<std::size_t>(T::bufferSize) * sizeof(typename T::DType);
55	};
56	
57	template <typename T>
58	inline constexpr std::size_t tile_storage_bytes_v = TileStorageBytes<T>::value;
59	
60	// =============================================================================
61	// BufferTraits: per-TileType capacity and alignment.
62	// =============================================================================
63	
64	template <TileType Loc>
65	struct BufferTraits;
66	
67	template <>
68	struct BufferTraits<TileType::Vec> {
69	    static constexpr std::size_t capacity = PTO_UBUF_SIZE_BYTES;
70	    static constexpr std::size_t alignment = PTO_UBUF_ALIGN_BYTES;
71	    static constexpr const char* name = "UB";
72	};
73	
74	template <>
75	struct BufferTraits<TileType::Mat> {
76	    static constexpr std::size_t capacity = PTO_CBUF_SIZE_BYTES;
77	    static constexpr std::size_t alignment = PTO_CBUF_ALIGN_BYTES;
78	    static constexpr const char* name = "L1";
79	};
80	
81	template <>
82	struct BufferTraits<TileType::Left> {
83	    static constexpr std::size_t capacity = PTO_L0A_SIZE_BYTES;
84	    static constexpr std::size_t alignment = PTO_L0A_ALIGN_BYTES;
85	    static constexpr const char* name = "L0A";
86	};
87	
88	template <>
89	struct BufferTraits<TileType::Right> {
90	    static constexpr std::size_t capacity = PTO_L0B_SIZE_BYTES;
91	    static constexpr std::size_t alignment = PTO_L0B_ALIGN_BYTES;
92	    static constexpr const char* name = "L0B";
93	};
94	
95	template <>
96	struct BufferTraits<TileType::Acc> {
97	    static constexpr std::size_t capacity = PTO_L0C_SIZE_BYTES;
98	    static constexpr std::size_t alignment = PTO_L0C_ALIGN_BYTES;
99	    static constexpr const char* name = "L0C";
100	};
101	
102	template <>
103	struct BufferTraits<TileType::Bias> {
104	    static constexpr std::size_t capacity = PTO_BIAS_SIZE_BYTES;
105	    static constexpr std::size_t alignment = PTO_BIAS_ALIGN_BYTES;
106	    static constexpr const char* name = "Bias";
107	};
108	
109	template <>
110	struct BufferTraits<TileType::Scaling> {
111	    static constexpr std::size_t capacity = PTO_FBUF_SIZE_BYTES;
112	    static constexpr std::size_t alignment = PTO_FBUF_ALIGN_BYTES;
113	    static constexpr const char* name = "FBuffer";
114	};
115	
116	template <>
117	struct BufferTraits<TileType::ScaleLeft> {
118	    static constexpr std::size_t capacity = PTO_SCALELEFT_SIZE_BYTES;
119	    static constexpr std::size_t alignment = PTO_L0A_ALIGN_BYTES;
120	    static constexpr const char* name = "L0A(Scale)";
121	};
122	
123	template <>
124	struct BufferTraits<TileType::ScaleRight> {
125	    static constexpr std::size_t capacity = PTO_SCALERIGHT_SIZE_BYTES;
126	    static constexpr std::size_t alignment = PTO_L0B_ALIGN_BYTES;
127	    static constexpr const char* name = "L0B(Scale)";
128	};
129	
130	// =============================================================================
131	// tassign_static_check: compile-time address validation for TASSIGN<Addr>(tile).
132	//
133	// Checks performed (SA-0351 .. SA-0354):
134	//   1. Memory space exists on this architecture (capacity != 0).
135	//   2. Tile storage size does not exceed memory space capacity.
136	//   3. addr + tile_size does not exceed memory space capacity.
137	//   4. addr is properly aligned.
138	// =============================================================================
139	
140	template <typename TileT, std::size_t Addr>
141	struct tassign_static_check {
142	    using Traits = BufferTraits<TileT::Loc>;
143	
144	    static constexpr std::size_t tile_bytes = tile_storage_bytes_v<TileT>;
145	    static constexpr std::size_t capacity = Traits::capacity;
146	    static constexpr std::size_t alignment = Traits::alignment;
147	    static constexpr std::size_t end_addr = Addr + tile_bytes;
148	
149	    // SA-0351: Memory space is not available on this architecture.
150	    // FIX-A12: Use a TileType whose memory space exists on the target
151	    //          architecture, or switch to a platform that supports this
152	    //          memory space (e.g. ScaleLeft/ScaleRight require A5).
153	    static_assert(
154	        capacity > 0, "[SA-0351] TASSIGN: memory space is not available on this architecture "
155	                      "(capacity is 0). (Fix: FIX-A12)");
156	
157	    // SA-0352: Tile storage size exceeds memory space capacity.
158	    // FIX-A12: Reduce the tile dimensions (Rows/Cols) or element type size,
159	    //          or override the capacity via -DPTO_xxx_SIZE_BYTES=<value>.
160	    static_assert(
161	        tile_bytes <= capacity, "[SA-0352] TASSIGN: Tile storage size exceeds memory space capacity. "
162	                                "Reduce tile dimensions or element size. (Fix: FIX-A12)");
163	
164	    // SA-0353: addr + tile_size exceeds memory space capacity (out of bounds).
165	    // FIX-A12: Choose a smaller Addr so that Addr + tile_size <= capacity,
166	    //          or reduce the tile size.
167	    static_assert(
168	        capacity == 0 || end_addr <= capacity,
169	        "[SA-0353] TASSIGN: addr + tile_size exceeds memory space capacity "
170	        "(out of bounds). Use a smaller address or reduce tile size. (Fix: FIX-A12)");
171	
172	    // SA-0354: addr is not properly aligned for the target memory space.
173	    // FIX-A12: Choose an Addr that is a multiple of the alignment requirement
174	    //          (see include/pto/common/buffer_limits.hpp for values).
175	    static_assert(
176	        alignment == 0 || (Addr % alignment) == 0,
177	        "[SA-0354] TASSIGN: addr is not properly aligned for the target memory space. "
178	        "Addr must be a multiple of the alignment (e.g. 32 bytes). (Fix: FIX-A12)");
179	};
180	
181	} // namespace detail
182	} // namespace pto
183	
184	#endif // __CPU_SIM
185	
186	#endif // PTO_COMMON_TASSIGN_CHECK_HPP
187

